const crypto = require('crypto');
const secret = String($env.N8N_WEBHOOK_SECRET || '');
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not configured in n8n'); }
const item = items[0];
const headers = item.json.headers || {};
const provided = String(headers['x-crm-signature'] || headers['X-CRM-Signature'] || '');

// The HMAC must be verified over the EXACT bytes the CRM signed. Laravel's json_encode escapes forward
// slashes and non-ASCII; JSON.stringify does not, so re-serializing the parsed body yields different
// bytes and a false mismatch on any realistic payload. Fail loudly rather than silently reject.
if (!(item.binary && item.binary.data && item.binary.data.data)) {
  throw new Error('Raw body unavailable -- enable the "Raw Body" option on the CRM Webhook node. Refusing to verify the HMAC over a re-serialized body.');
}
const raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex');
const ok = provided.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(provided), Buffer.from(expected));
if (!ok) { throw new Error('Invalid X-CRM-Signature -- webhook rejected'); }
const env = JSON.parse(raw);

// Topic guard first: the CRM routes each topic to its own path, so a foreign topic is a misconfiguration.
if (env.topic !== 'deal.won') { return []; }

// Replay window: a signed-but-stale envelope is rejected (dedupe alone cannot bound replay).
const MAX_AGE_MS = 15 * 60 * 1000;
const occurred = Date.parse(env.occurred_at || '');
if (Number.isFinite(occurred) && (Date.now() - occurred) > MAX_AGE_MS) {
  throw new Error('Envelope outside the replay window -- rejected');
}

// Idempotency: dedupe on the envelope event_id (at-least-once delivery). Entries are pruned on a TTL so
// the static store cannot grow without bound.
const sd = $getWorkflowStaticData('global');
const TTL_MS = 24 * 60 * 60 * 1000;
const now = Date.now();
sd.seen = sd.seen || {};
for (const k of Object.keys(sd.seen)) { if (now - sd.seen[k] > TTL_MS) { delete sd.seen[k]; } }
if (env.event_id && sd.seen[env.event_id]) { return []; }
if (env.event_id) { sd.seen[env.event_id] = now; }

const data = env.data || {};
const event_id = env.event_id || null;
if (!data.lead_id) { return []; }
return [{ json: { lead_id: data.lead_id, event_id } }];
